mapper.update:
UPDATE payments
SET payment_status = #{paymentStatus},
    transaction_id = #{transactionId},
    payment_time = #{paymentTime},
    updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}

UPDATE payments 
SET payment_method = #{paymentMethod},
    updated_at = #{updatedAt} 
WHERE payment_id = #{paymentId}

UPDATE payments
payment_method = #{paymentMethod}, payment_amount = #{paymentAmount}, payment_status = #{paymentStatus}, transaction_id = #{transactionId}, payment_time = #{paymentTime}, refund_time = #{refundTime}, refund_amount = #{refundAmount}, refund_reason = #{refundReason}, payment_expiry = #{paymentExpiry}, payment_notes = #{paymentNotes}, updated_at = #{updatedAt}
WHERE payment_id = #{paymentId}

UPDATE payments
SET payment_status = 'FAILED',
    payment_notes = CONCAT(IFNULL(payment_notes, ''), '; 系统自动标记：支付超时'),
    updated_at = #{currentTime}
WHERE payment_status = 'PENDING'
  AND payment_expiry < #{currentTime}

mapper.select:
SELECT * FROM payments

    AND payment_id = #{paymentId}
    AND purchase_id = #{purchaseId}
    AND customer_id = #{customerId}
    AND payment_method = #{paymentMethod}
    AND payment_status = #{paymentStatus}
    AND transaction_id = #{transactionId}

ORDER BY created_at DESC

SELECT COUNT(*) FROM payments

    AND payment_id = #{paymentId}
    AND purchase_id = #{purchaseId}
    AND customer_id = #{customerId}
    AND payment_method = #{paymentMethod}
    AND payment_status = #{paymentStatus}
    AND transaction_id = #{transactionId}

SELECT * FROM payments
WHERE payment_status = 'PENDING'
  AND payment_expiry > #{currentTime}
  AND TIMESTAMPDIFF(MINUTE, #{currentTime}, payment_expiry) <= #{minutes}
ORDER BY payment_expiry ASC
